34	constexpr std::string_view kVerifyUsage =
35	    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
36	    "--tag-hex <hex-tag>\n"
37	    "       (a <message-file> of exactly '-' reads the message from "
