150	// Parse options of the form "--name value" starting at argv[2]. On a usage
151	// problem (an unknown argument, or an option without a following value) a
152	// command-specific diagnostic and the usage line are written to stderr and
153	// this returns false; the caller then exits with code 2. On success the
154	// collected values are stored keyed by option name, and the caller checks
155	// which required options are present. Only the value-taking options named
156	// in `names` are accepted.
157	//
158	// An option's value is missing not only when nothing follows it, but also
159	// when the next token is itself one of this command's option names: in
160	// "--file --file" the second "--file" is another option, not a file name,
161	// so the first "--file" is reported as missing a value instead of
162	// consuming the option as its value. Only an exact match with a recognized
163	// option name triggers this; any other token (including one that merely
164	// starts with a dash, such as "--notes", and including an explicitly empty
165	// string) is taken as the value, so file paths with leading dashes stay
166	// usable and empty values keep their own distinct diagnostics.
167	bool parseValueOptions(const CommandSpec& spec, int argc, char* argv[],
168	                       std::map<std::string, std::string>& values) {
169	    auto isOptionName = [&spec](std::string_view arg) {
170	        for (std::string_view name : spec.options) {
171	            if (arg == name) {
172	                return true;
173	            }
174	        }
175	        return false;
176	    };
177	    for (int i = 2; i < argc; ++i) {
178	        std::string arg(argv[i]);
179	        if (!isOptionName(arg)) {
180	            std::cerr << "messagetag " << spec.name
181	                      << ": error: unknown argument '" << arg << "'\n"
182	                      << spec.usage;
183	            return false;
184	        }
185	        // The diagnostic names only the option that lacks a value; the
186	        // following token (a recognized option name, or nothing at all) is
187	        // never spliced into the message, and neither is any key or tag
188	        // material supplied elsewhere on the command line.
189	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
190	            std::cerr << "messagetag " << spec.name
191	                      << ": error: option '" << arg
192	                      << "' requires a value\n"
193	                      << spec.usage;
194	            return false;
195	        }
196	        values[arg] = argv[++i];
197	    }
198	    return true;
199	}
