229	// The outcome of authenticating one message: the tag was produced, the
230	// message source failed, or the HMAC computation itself failed.
231	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
232	
233	// A streaming HMAC-SHA-256 computation: Init with the key at construction,
234	// feed message bytes chunk by chunk with update(), produce the tag once
235	// with finish(). All message sources feed their bytes through this one
236	// path, so the same key and the same bytes always yield the same tag no
237	// matter which source they came from, and no matter how the input was
238	// split into reads.
239	//
240	// HMAC_Init_ex performs the standard RFC 2104 key normalization itself, so
241	// keys longer than the SHA-256 block size are hashed exactly as the
242	// standard requires; the resulting tag is identical to the one-shot HMAC()
243	// interface on both OpenSSL 1.1.1 and OpenSSL 3.x. The key is validated to
244	// be non-empty before this is constructed, so key.data() is always valid.
245	class HmacSha256Stream {
246	  public:
247	    explicit HmacSha256Stream(const std::vector<unsigned char>& key)
248	        : ctx_(HMAC_CTX_new(), &HMAC_CTX_free) {
249	        usable_ = ctx_ != nullptr &&
250	                  HMAC_Init_ex(ctx_.get(), key.data(),
251	                               static_cast<int>(key.size()), EVP_sha256(),
252	                               nullptr) == 1;
253	    }
254	
255	    bool usable() const { return usable_; }
256	
257	    bool update(const char* data, std::size_t length) {
258	        return HMAC_Update(ctx_.get(),
259	                           reinterpret_cast<const unsigned char*>(data),
260	                           length) == 1;
261	    }
262	
263	    bool finish(std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
264	                std::size_t& macLength) {
265	        unsigned int outLength = 0;
266	        if (HMAC_Final(ctx_.get(), mac.data(), &outLength) != 1) {
267	            return false;
268	        }
269	        macLength = outLength;
270	        return true;
271	    }
272	
273	  private:
274	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx_;
275	    bool usable_ = false;
276	};
