278	// A message source delivers the message one chunk at a time through
279	// readChunk(): fill `buffer` with up to `capacity` bytes and return how
280	// many were delivered, return 0 once the message has ended normally, or
281	// return -1 when the source fails (after which no further bytes are
282	// requested). How a chunk is obtained -- and what counts as a failure --
283	// is each source's own business; the shared authentication below only
284	// ever sees the resulting byte stream.
285	
286	// A file source delivers the file's raw bytes exactly as stored: they
287	// are not interpreted as text, trailing newlines are kept, line endings
288	// are not converted and zero bytes are preserved. An empty file ends
289	// immediately, which authenticates the empty message. Failing to open
290	// the file is a read failure reported on the first chunk.
291	class FileMessageSource {
292	  public:
293	    explicit FileMessageSource(const std::string& path)
294	        : in_(path, std::ios::binary | std::ios::in), failed_(!in_) {}
295	
296	    ssize_t readChunk(char* buffer, std::size_t capacity) {
297	        if (failed_) {
298	            return -1;
299	        }
300	        if (ended_) {
301	            return 0;
302	        }
303	        in_.read(buffer, static_cast<std::streamsize>(capacity));
304	        // badbit means the read itself failed -- possibly after a
305	        // non-empty prefix was already delivered. A short read at EOF
306	        // is normal, and those remaining bytes still participate; the
307	        // zero-byte read past the end is the normal end of the message.
308	        if (in_.bad()) {
309	            failed_ = true;
310	            return -1;
311	        }
312	        if (in_.eof()) {
313	            ended_ = true;
314	        }
315	        return static_cast<ssize_t>(in_.gcount());
316	    }
317	
318	  private:
319	    std::ifstream in_;
320	    bool failed_ = false;
321	    bool ended_ = false;
322	};
323	
324	// A standard-input source (selected by "--file -") delivers every byte
325	// that arrives on file descriptor 0 until the input ends normally (EOF).
326	// Bytes arriving in several installments are simply several chunks,
327	// which does not change the message. A read interrupted by EINTR before
328	// any byte arrived is retried in place: the bytes received so far still
329	// belong to the same message. Any other read failure ends the source
330	// with an error.
331	class StdinMessageSource {
332	  public:
333	    ssize_t readChunk(char* buffer, std::size_t capacity) {
334	        for (;;) {
335	            ssize_t n = ::read(STDIN_FILENO, buffer, capacity);
336	            if (n >= 0) {
337	                return n;  // n == 0 is the clean end of input
338	            }
339	            if (errno != EINTR) {
340	                return -1;
341	            }
342	        }
343	    }
344	};
