346	// The single place that maintains how a message is authenticated: start
347	// HMAC-SHA-256 with the key, feed every chunk the source delivers in the
348	// order it arrives, and finish exactly once, when the source reports the
349	// message has ended normally. Both sources feed their bytes through this
350	// one path, so the same key and the same bytes always yield the same tag
351	// no matter which source they came from, no matter how the input was
352	// split into reads, and no matter whether the last read filled the
353	// buffer.
354	//
355	// The message is never stored whole: regardless of its length, only one
356	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
357	// A read failure -- including one after a non-empty prefix has already
358	// been fed to HMAC -- aborts authentication: finish() is never reached,
359	// so the received prefix can never be finalized as if it were the whole
360	// message.
361	template <typename Source>
362	HmacStatus authenticateMessage(const std::vector<unsigned char>& key,
363	                               Source& source,
364	                               std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
365	                               std::size_t& macLength) {
366	    HmacSha256Stream hmac(key);
367	    if (!hmac.usable()) {
368	        return HmacStatus::kCryptoError;
369	    }
370	
371	    std::array<char, 65536> buffer{};
372	    for (;;) {
373	        ssize_t n = source.readChunk(buffer.data(), buffer.size());
374	        if (n > 0) {
375	            if (!hmac.update(buffer.data(), static_cast<std::size_t>(n))) {
376	                return HmacStatus::kCryptoError;
377	            }
378	            continue;
379	        }
380	        if (n == 0) {
381	            break;  // clean end of the message: every byte has been fed
382	        }
383	        return HmacStatus::kReadError;
384	    }
385	
386	    if (!hmac.finish(mac, macLength)) {
387	        return HmacStatus::kCryptoError;
388	    }
389	    return HmacStatus::kSuccess;
390	}
