392	// Output of the shared preparation stage that the command-specific
393	// decision still needs afterwards.
394	struct PreparedAuthentication {
395	    // verify only: the supplied --tag-hex decoded to 32 bytes; unused by
396	    // tag, which has no tag to compare against.
397	    std::vector<unsigned char> expectedTag;
398	};
