400	// Prepare and perform the message authentication that both commands share.
401	// This is the single place that maintains the ordered checks leading up to
402	// the command-specific result:
403	//
404	//   1. parse exactly this command's value-taking options (unknown argument
405	//      or missing value -> exit 2 with that command's usage);
406	//   2. require --key-hex/--file, and additionally --tag-hex when
407	//      `expectTag` is set (exit 2);
408	//   3. decode the key, and the supplied tag for verify, BEFORE the message
409	//      source is touched, so a malformed key/tag is a parameter error
410	//      (exit 2) even when the file does not exist -- and, with "--file -",
411	//      without waiting for standard input to arrive or end;
412	//   4. stream the whole message through HMAC-SHA-256, from the named file
413	//      or -- when --file is exactly "-" -- from standard input until its
414	//      normal end (read or computation failure -> exit 1, with no result
415	//      produced; a prefix read before a failure is never finalized as the
416	//      message).
417	//
418	// Every diagnostic goes out from here under the failing command's own name
419	// and usage, so one and the same failure behaviour no longer has to be kept
420	// in sync between runTag and runVerify. Returns the process exit code; on
421	// success it is 0 and `mac`/`macLength` (plus `prepared` for verify) hold
422	// what the caller needs for its own result handling; otherwise the caller
423	// returns the non-zero code unchanged.
424	int prepareAuthentication(const CommandSpec& spec, int argc, char* argv[],
425	                          bool expectTag,
426	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
427	                          std::size_t& macLength,
428	                          PreparedAuthentication& prepared) {
429	    std::map<std::string, std::string> opts;
430	    if (!parseValueOptions(spec, argc, argv, opts)) {
431	        return 2;
432	    }
433	    if (!requireOption(spec, opts, "--key-hex") ||
434	        !requireOption(spec, opts, "--file") ||
435	        (expectTag && !requireOption(spec, opts, "--tag-hex"))) {
436	        return 2;
437	    }
438	    const std::string& keyHex = opts["--key-hex"];
439	    const std::string& filePath = opts["--file"];
440	
441	    // All input-format checks happen before the message source is touched,
442	    // so a malformed key or tag is reported as a parameter error (exit 2)
443	    // even when the message file does not exist -- and, with "--file -",
444	    // without ever waiting for standard input.
445	    std::vector<unsigned char> key;
446	    if (!parseKey(spec, keyHex, key)) {
447	        return 2;
448	    }
449	
450	    if (expectTag) {
451	        // The supplied tag must decode to exactly 32 bytes (64 hex
452	        // characters); decodeHex already rejects empty input, odd length,
453	        // non-hex characters and whitespace, which also rules out a 0x
454	        // prefix. The submitted tag is deliberately not echoed back.
455	        if (!decodeHex(opts["--tag-hex"], prepared.expectedTag) ||
456	            prepared.expectedTag.size() != kTagBytes) {
457	            std::cerr << "messagetag " << spec.name
458	                      << ": error: invalid --tag-hex: expected exactly 64 "
459	                         "hexadecimal characters denoting 32 bytes (0-9, a-f, "
460	                         "A-F); empty, truncated or over-long values, embedded "
461	                         "whitespace and a 0x prefix are not accepted\n"
462	                      << spec.usage;
463	            return 2;
464	        }
465	    }
466	
467	    // A --file value of exactly "-" reads the message from standard input
468	    // until its normal end; a file literally named "-" stays reachable as
469	    // "./-" or by full path, and every other value is a file path read the
470	    // usual way. Either way the bytes go through the one shared
471	    // authenticateMessage() above; only the source differs.
472	    const bool fromStdin = filePath == "-";
473	    HmacStatus status;
474	    if (fromStdin) {
475	        StdinMessageSource source;
476	        status = authenticateMessage(key, source, mac, macLength);
477	    } else {
478	        FileMessageSource source(filePath);
479	        status = authenticateMessage(key, source, mac, macLength);
480	    }
481	    switch (status) {
482	        case HmacStatus::kReadError:
483	            // The partially read prefix must never be authenticated as if
484	            // it were the whole message. Neither diagnostic echoes the key,
485	            // the supplied tag or a recomputed tag.
486	            if (fromStdin) {
487	                std::cerr << "messagetag " << spec.name
488	                          << ": error: failed to read standard input\n";
489	            } else {
490	                std::cerr << "messagetag " << spec.name
491	                          << ": error: failed to read file: " << filePath
492	                          << "\n";
493	            }
494	            return 1;
495	        case HmacStatus::kCryptoError:
496	            std::cerr << "messagetag " << spec.name
497	                      << ": error: HMAC-SHA-256 computation failed\n";
498	            return 1;
499	        case HmacStatus::kSuccess:
500	            return 0;
501	    }
502	    return 1;  // unreachable: every status is handled above
503	}
504	
505	int runTag(int argc, char* argv[]) {
506	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
507	    std::size_t macLength = 0;
508	    PreparedAuthentication prepared;
509	    int rc = prepareAuthentication(tagSpec(), argc, argv, /*expectTag=*/false,
510	                                   mac, macLength, prepared);
511	    if (rc != 0) {
512	        return rc;
513	    }
514	
515	    std::string tagLine = hexEncode(mac.data(), macLength);
516	    tagLine.push_back('\n');
517	    // Exit 0 only once the whole line is confirmed written; a correct tag
518	    // does not make a failed/partial result output a success.
519	    if (!emitResultLine("tag", tagLine)) {
520	        return 1;
521	    }
522	    return 0;
523	}
