525	// Compare two fixed-length byte strings without leaking the length of any
526	// matching prefix: the loop always touches every byte and accumulates all
527	// differences, so the running time does not depend on where (or whether)
528	// the inputs differ.
529	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
530	                       std::size_t length) {
531	    unsigned char diff = 0;
532	    for (std::size_t i = 0; i < length; ++i) {
533	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
534	    }
535	    return diff == 0;
536	}
