538	int runVerify(int argc, char* argv[]) {
539	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
540	    std::size_t macLength = 0;
541	    PreparedAuthentication prepared;
542	    int rc = prepareAuthentication(verifySpec(), argc, argv,
543	                                   /*expectTag=*/true, mac, macLength,
544	                                   prepared);
545	    if (rc != 0) {
546	        return rc;
547	    }
548	
549	    if (macLength != kTagBytes ||
550	        !constantTimeEqual(mac.data(), prepared.expectedTag.data(),
551	                           kTagBytes)) {
552	        // State only that authentication failed; do not assign a cause (the
553	        // message, the key or the tag could each be the one that differs),
554	        // and never print the recomputed tag, a matched prefix or the key.
555	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
556	                     "the supplied tag does not match the given key and file "
557	                     "content\n";
558	        return 3;
559	    }
560	
561	    // Exit 0 only once the whole "OK\n" line is confirmed written; a
562	    // passed comparison does not make a failed/partial result output a
563	    // success.
564	    if (!emitResultLine("verify", "OK\n")) {
565	        return 1;
566	    }
567	    return 0;
568	}
